import { BoxGeometry, Mesh, MeshBasicMaterial, Object3D } from '@iwsdk/core';
import { DEFENSE_BUTTONS } from './level-config.js';

/**
 * Build/repair button rigs.
 *
 * The visible glyphs are designed assets now: `gltf/defense-button-build.glb`
 * (siege mallet, brass family) and `gltf/defense-button-repair.glb` (service
 * wrench, signal-green family), generated by `npm run export-assets`. Each
 * carries one merged `button-icon` mesh — white dielectric PBR (roughness
 * 0.5, metalness 0) with the colour zones baked into vertex colors, so the
 * icons sit in the same material family as the wall, cannons and ballistas.
 *
 * State visuals stay runtime-side and cheap: DefenseButtonSystem shrinks
 * the open slot's build icon and breathes the repair icon — both pure
 * scale writes on the icon mesh; materials and the hit proxies never
 * change. The glyph needs no shadow participation — both shadow flags are
 * forced off below.
 *
 * The invisible hit proxy is a box that renders nothing (colorWrite off) yet
 * stays raycastable — object.visible is what raycasters key on, not material
 * color. Each kind's box is deliberately larger than its glyph so a thumb or
 * XR ray never has to land on the icon itself, and is trimmed in X so the
 * build/repair pair never overlap.
 */

/**
 * Shared invisible-hit-proxy geometry/material per kind — renders nothing,
 * hits all. Tall boxes sized over the baked 1.2x glyphs and trimmed in X so
 * the build/repair pair (and neighbouring slots) never overlap: a raycast
 * landing in the seam always has exactly one winner.
 */
const PROXY_GEOMETRIES = {
  build: new BoxGeometry(
    DEFENSE_BUTTONS.proxyBuild.x,
    DEFENSE_BUTTONS.proxyBuild.y,
    DEFENSE_BUTTONS.proxyBuild.z,
  ),
  repair: new BoxGeometry(
    DEFENSE_BUTTONS.proxyRepair.x,
    DEFENSE_BUTTONS.proxyRepair.y,
    DEFENSE_BUTTONS.proxyRepair.z,
  ),
} as const;
const PROXY_MATERIAL = new MeshBasicMaterial({
  colorWrite: false,
  depthWrite: false,
  transparent: true,
});

export type ButtonKind = 'build' | 'repair';

/**
 * One button rig: a clone of the icon's GLB prototype (the `button-icon`
 * mesh keeps its baked vertex colors; clones share geometry and material)
 * plus the invisible hit proxy, centred on its mount point facing +Z. The
 * caller creates the transform entity, adds RayInteractable + DefenseButton
 * and owns placement (battle-setup); DefenseButtonSystem resolves the icon
 * mesh by name for its per-frame state writes.
 */
export function createDefenseButtonRig(
  kind: ButtonKind,
  prototype: Object3D,
): Object3D {
  const rig = prototype.clone(true);
  rig.name = `defense-button-${kind}`;
  rig.traverse((child: Object3D) => {
    if ((child as Mesh).isMesh) {
      child.castShadow = false;
      child.receiveShadow = false;
    }
  });

  const proxy = new Mesh(PROXY_GEOMETRIES[kind], PROXY_MATERIAL);
  proxy.name = 'button-proxy';
  proxy.castShadow = false;
  proxy.receiveShadow = false;

  rig.add(proxy);
  return rig;
}
